pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 deposit, uint256 unlockTime, uint256 collectAmount) public {
        // Constrain parameters to satisfy the contract's requirements
        vm.assume(caller != address(0) && caller != address(c));
        vm.assume(deposit >= 1 ether); // at least MinSum
        vm.assume(collectAmount <= deposit);
        unlockTime = bound(unlockTime, block.timestamp, block.timestamp + 365 days);

        // Fund the caller and deposit
        vm.deal(caller, deposit);
        vm.prank(caller);
        c.Put(unlockTime);

        // Record balance before Collect
        uint256 balanceBefore = c.Acc(caller).balance;

        // Warp to after unlockTime
        vm.warp(unlockTime + 1);

