contract InvMutTest is Test {
    C c;
    uint256 totalPut;

    function setUp() public {
        c = new C(address(this));
    }

    function testFuzz_property(address caller, uint256 putAmount, uint256 collectAmount, uint256 unlockTime) public {
        vm.assume(caller != address(0) && caller != address(c));
        putAmount = bound(putAmount, 0.1 ether, 5 ether);
        collectAmount = bound(collectAmount, 0, putAmount);
        unlockTime = bound(unlockTime, block.timestamp, block.timestamp + 100);

        // First Put
        vm.deal(caller, putAmount);
        vm.prank(caller);
        c.Put{value: putAmount}(unlockTime);
        totalPut += putAmount;

        // Fast forward past unlockTime
        vm.warp(unlockTime + 1);

        // Record balances before Collect
        uint256 contractBalBefore = address(c).balance;
        uint256 callerAccBalBefore = c.Acc(caller).balance;

        // Call Collect
        vm.prank(caller);
        c.Collect(collectAmount);

        // Balances after
        uint256 contractBalAfter = address(c).balance;
        uint256 callerAccBalAfter = c.Acc(caller).balance;

        // Sum of contract balance + all user balances (only caller has non-zero balance)
        uint256 sumBefore = contractBalBefore + callerAccBalBefore;
        uint256 sumAfter = contractBalAfter + callerAccBalAfter;

        // The invariant: total amount in contract (contract balance + user balances) equals totalPut
        // This holds because no other Ether moves in/out besides Put/Collect.
        assertTrue(sumAfter == totalPut, "Invariant broken");
