        depositAmount = bound(depositAmount, 1 ether, 100 ether);
        withdrawAmount = bound(withdrawAmount, 0, depositAmount);

        // Ensure the caller has enough ether
        vm.deal(address(0x123), depositAmount);
        vm.prank(address(0x123));
        // First, deposit funds
        (bool successDeposit,) = address(c).call{value: 1 ether}(abi.encodeWithSignature("Put(uint256)", block.timestamp + 100));

        if (!successDeposit) return; // If deposit fails, skip

        // Now attempt to withdraw
        uint256 balanceBefore = address(c).balance;
        (bool successWithdraw,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", withdrawAmount));
        uint256 balanceAfter = address(c).balance;

        if (successWithdraw) {
            // If withdrawal succeeds, contract balance should decrease by withdrawAmount
            assertTrue(balanceAfter <= balanceBefore, "Balance should not increase on withdrawal");
            assertTrue(balanceBefore - balanceAfter == withdrawAmount, "Contract balance should decrease by exact withdrawal amount");
        } else {
            // If withdrawal reverts, it could be due to insufficient balance or lock
            // But the lock bug would cause a permanent revert on subsequent calls
            // So verify that a second withdrawal can succeed if balance is sufficient
            if (balanceBefore >= withdrawAmount) {
                // Balance is sufficient, so failure indicates a bug
                assertTrue(false, "Withdrawal should succeed when balance is sufficient");
            }
        }
    }
}

